/* Pure SI models. Rendering and storage live in lab.js. No numerical time drift. */
(function(root){
'use strict';
const g=9.81,R=8.314462618,hEv=4.135667696e-15,rad=d=>d*Math.PI/180;
const p=(key,label,min,max,step,value,unit='')=>({key,label,min,max,step,value,unit});
const m=(key,label,unit)=>({key,label,unit});
const labs=[
{id:'projectile',title:'Бросок под углом',group:'Механика',grade:'9–10',symbol:'↗',intro:'Найди угол наибольшей дальности и отдели горизонтальное движение от вертикального.',params:[p('v','Начальная скорость',5,40,1,20,'м/с'),p('angle','Угол броска',10,80,1,45,'°'),p('g','Ускорение тяжести',1.6,20,.01,g,'м/с²')],duration:p=>2*p.v*Math.sin(rad(p.angle))/p.g,
calc(p,t){const vx=p.v*Math.cos(rad(p.angle)),vy0=p.v*Math.sin(rad(p.angle)),T=2*vy0/p.g; t=Math.min(t,T);return{x:vx*t,y:Math.max(0,vy0*t-p.g*t*t/2),vy:vy0-p.g*t,vx,T,range:vx*T,H:vy0*vy0/(2*p.g)}},metrics:[m('x','Дальность сейчас','м'),m('y','Высота','м'),m('vy','Вертикальная скорость','м/с'),m('range','Полная дальность','м')],graph:{key:'y',label:'Высота y',unit:'м'},formula:'x = v₀ cos α · t; y = v₀ sin α · t − gt²/2',explain:'Горизонтальная скорость постоянна, а вертикальная каждую секунду уменьшается на g. При одинаковой высоте старта и приземления углы α и 90° − α дают одинаковую дальность.',limits:'Материальная точка; сопротивления воздуха нет; старт и приземление на одной высоте. После касания земли опыт заканчивается.',steps:['Поставь 30° и запиши полную дальность. Закрепи график для сравнения.','Повтори для 60°, затем для 45°. Скорость и g оставь прежними.','Объясни, почему при одинаковой дальности время полёта и высота различаются.'],question:'Рассчитай максимальную высоту полёта, м.',answer:(p,r)=>r.H,solution:'В вершине vᵧ = 0. Из vᵧ² = (v₀ sin α)² − 2gH получаем H = (v₀ sin α)² / (2g).',presets:[['Земля',{g:9.81}],['Луна',{g:1.62}]]},
{id:'incline',title:'Наклонная плоскость',group:'Механика',grade:'9–10',symbol:'∠',intro:'Когда тело начинает скользить? Сравни силу тяжести и трение.',params:[p('angle','Наклон',5,60,1,30,'°'),p('mu','Коэффициент трения',0,.8,.01,.2),p('mass','Масса',.5,10,.5,2,'кг'),p('length','Длина склона',1,10,.5,5,'м')],duration(p){const a=g*Math.max(0,Math.sin(rad(p.angle))-p.mu*Math.cos(rad(p.angle)));return a>1e-8?Math.sqrt(2*p.length/a):5},calc(p,t){const normal=p.mass*g*Math.cos(rad(p.angle)),along=p.mass*g*Math.sin(rad(p.angle)),friction=Math.min(along,p.mu*normal),a=(along-friction)/p.mass,s=Math.min(p.length,a*t*t/2);return{normal,friction,a,s,v:Math.sqrt(2*a*s),work:friction*s}},metrics:[m('a','Ускорение','м/с²'),m('v','Скорость','м/с'),m('normal','Реакция опоры','Н'),m('friction','Сила трения','Н')],graph:{key:'v',label:'Скорость v',unit:'м/с'},formula:'N = mg cos α; a = max(0, g(sin α − μ cos α))',explain:'Пока mg sin α не превышает μN, трение удерживает тело. После начала скольжения оно направлено вверх по склону. В этой модели ускорение не зависит от массы.',limits:'Тело стартует из покоя. Коэффициенты трения покоя и скольжения приняты одинаковыми. Движение заканчивается у края плоскости.',steps:['Найди угол начала движения при μ = 0,4.','Увеличь массу вдвое, сохрани наклон и трение. Сравни ускорения.','Запиши баланс энергии: mgs sin α = mv²/2 + Fтрs.'],question:'Найди реакцию опоры N, Н.',answer:(p,r)=>r.normal,solution:'Проекция ускорения поперёк плоскости равна нулю, поэтому N = mg cos α. Здесь g = 9,81 м/с².',presets:[['Без трения',{mu:0}],['Тело удерживается',{angle:15,mu:.5}]]},
{id:'collision',title:'Столкновение тел',group:'Механика',grade:'9–10',symbol:'⇄',intro:'Проверь сохранение импульса и выясни, куда уходит кинетическая энергия.',params:[p('m1','Масса первого тела',.5,5,.5,1,'кг'),p('m2','Масса второго тела',.5,5,.5,2,'кг'),p('u1','Скорость первого',1,5,.5,3,'м/с'),p('u2','Скорость второго',-3,0,.5,-1,'м/с'),p('e','Коэффициент восстановления',0,1,.05,1)],duration:p=>2/(p.u1-p.u2)+2,calc(p,t){const P=p.m1*p.u1+p.m2*p.u2,M=p.m1+p.m2,v1=(P-p.m2*p.e*(p.u1-p.u2))/M,v2=(P+p.m1*p.e*(p.u1-p.u2))/M,tc=2/(p.u1-p.u2),hit=t>=tc,a=hit?v1:p.u1,b=hit?v2:p.u2;return{tc,v1:a,v2:b,x1:hit?p.u1*tc+v1*(t-tc):p.u1*t,x2:hit?2+p.u2*tc+v2*(t-tc):2+p.u2*t,P:p.m1*a+p.m2*b,E:(p.m1*a*a+p.m2*b*b)/2,loss:(p.m1*p.u1*p.u1+p.m2*p.u2*p.u2-p.m1*v1*v1-p.m2*v2*v2)/2,after1:v1,after2:v2}},metrics:[m('v1','Скорость тела 1','м/с'),m('v2','Скорость тела 2','м/с'),m('P','Полный импульс','кг·м/с'),m('E','Кинетическая энергия','Дж')],graph:{key:'E',label:'Энергия системы',unit:'Дж'},formula:'m₁u₁ + m₂u₂ = m₁v₁ + m₂v₂; v₂ − v₁ = e(u₁ − u₂)',explain:'Импульс замкнутой системы сохраняется при любом e. При e = 1 удар упругий. При e = 0 тела после удара движутся вместе; потеря механической энергии максимальна.',limits:'Одномерный мгновенный удар без внешних сил. Расстояние между контактными гранями в начале — 2 м. Размеры тел на рисунке условные.',steps:['Сделай массы одинаковыми и e = 1. Проследи обмен скоростями.','Запиши энергию до и после удара при e = 0,5.','Для e = 0 рассчитай общую скорость из закона сохранения импульса.'],question:'Какой будет скорость первого тела после удара, м/с? Учитывай знак.',answer:(p,r)=>r.after1,solution:'Реши систему двух уравнений: v₁ = [m₁u₁ + m₂u₂ − m₂e(u₁ − u₂)] / (m₁ + m₂).',presets:[['Обмен скоростями',{m1:1,m2:1,e:1}],['Сцепление',{e:0}]]},
{id:'pendulum',title:'Математический маятник',group:'Механика',grade:'9–11',symbol:'◴',intro:'Измерь период и проверь, почему масса груза не определяет ход маятника.',params:[p('length','Длина нити',.2,3,.05,1,'м'),p('angle','Амплитуда',2,15,.5,10,'°'),p('mass','Масса груза',.1,2,.1,.5,'кг'),p('g','Ускорение тяжести',1.6,20,.01,g,'м/с²')],duration:p=>4*2*Math.PI*Math.sqrt(p.length/p.g),calc(p,t){const omega=Math.sqrt(p.g/p.length),A=rad(p.angle),theta=A*Math.cos(omega*t),v=-p.length*A*omega*Math.sin(omega*t),U=p.mass*p.g*p.length*theta*theta/2;return{theta:theta*180/Math.PI,v,T:2*Math.PI/omega,K:p.mass*v*v/2,U,E:p.mass*p.g*p.length*A*A/2}},metrics:[m('theta','Отклонение','°'),m('v','Скорость по дуге','м/с'),m('T','Период','с'),m('E','Полная энергия','Дж')],graph:{key:'theta',label:'Угол θ',unit:'°'},formula:'θ = θ₀ cos(√(g/l) · t); T = 2π√(l/g)',explain:'Возвращающая сила растёт с отклонением. Для малых углов sin θ ≈ θ, и движение становится гармоническим. Увеличение длины в четыре раза удваивает период.',limits:'Малые углы до 15°, невесомая нерастяжимая нить, без сопротивления. Энергия рассчитана в том же приближении: U = mglθ²/2.',steps:['По шкале времени измерь один полный цикл.','Сравни периоды при l = 0,5 и 2 м.','Поменяй массу и объясни, что меняется в энергии, но не в периоде.'],question:'Вычисли период маятника, с.',answer:(p,r)=>r.T,solution:'T = 2π√(l/g). Масса и амплитуда в формулу малых колебаний не входят.',presets:[['Короткая нить',{length:.5}],['Длинная нить',{length:2}]]},
{id:'spring',title:'Пружинный осциллятор',group:'Механика',grade:'9–11',symbol:'∿',intro:'Проследи превращение энергии пружины в кинетическую энергию груза.',params:[p('mass','Масса',.1,3,.1,1,'кг'),p('k','Жёсткость',5,100,1,20,'Н/м'),p('A','Амплитуда',.05,.5,.01,.25,'м')],duration:p=>4*2*Math.PI*Math.sqrt(p.mass/p.k),calc(p,t){const w=Math.sqrt(p.k/p.mass),x=p.A*Math.cos(w*t),v=-p.A*w*Math.sin(w*t);return{x,v,F:-p.k*x,K:p.mass*v*v/2,U:p.k*x*x/2,E:p.k*p.A*p.A/2,T:2*Math.PI/w}},metrics:[m('x','Смещение','м'),m('K','Кинетическая энергия','Дж'),m('U','Энергия пружины','Дж'),m('E','Полная энергия','Дж')],graph:{key:'x',label:'Смещение x',unit:'м'},formula:'x = A cos(√(k/m) · t); E = kA²/2 = K + U',explain:'В крайних положениях скорость равна нулю, а энергия пружины максимальна. В равновесии всё запасённое движение проявляется как кинетическая энергия.',limits:'Горизонтальная невесомая идеальная пружина, закон Гука, трения нет. Смещение отсчитывается от равновесия.',steps:['Запиши K и U в крайнем положении и в равновесии.','Удвой амплитуду и сравни полную энергию.','Увеличь массу в четыре раза: проверь изменение периода.'],question:'Найди максимальную скорость, м/с.',answer:p=>p.A*Math.sqrt(p.k/p.mass),solution:'При x = 0 вся энергия кинетическая: mv²/2 = kA²/2, поэтому vₘₐₓ = A√(k/m).',presets:[['Мягкая пружина',{k:10}],['Жёсткая пружина',{k:80}]]},
{id:'buoyancy',title:'Сила Архимеда',group:'Жидкости',grade:'7–8',symbol:'≈',intro:'Погружай тело и сравнивай вес с выталкивающей силой.',params:[p('rho','Плотность жидкости',700,1300,10,1000,'кг/м³'),p('body','Плотность тела',400,2500,50,800,'кг/м³'),p('volume','Объём тела',.5,5,.1,2,'л'),p('part','Погружено',0,100,1,50,'%')],sweep:'part',calc(p){const V=p.volume/1000,F=p.rho*g*V*p.part/100,weight=p.body*V*g;return{F,weight,hold:weight-F,equilibrium:Math.min(100,p.body/p.rho*100),net:F-weight}},metrics:[m('F','Сила Архимеда','Н'),m('weight','Вес mg','Н'),m('hold','Поддерживающая сила ↑','Н'),m('net','Равнодействующая без опоры ↑','Н')],graph:{key:'F',label:'Сила Архимеда',unit:'Н'},formula:'Fₐ = ρжgVпогр; Fподд = mg − Fₐ',explain:'Выталкивающая сила равна весу вытесненной жидкости. Плавающее тело выбирает глубину, при которой Fₐ = mg. Если ρт > ρж, даже полного погружения недостаточно для равновесия без опоры.',limits:'Тело удерживается на заданной глубине внешней силой. Отрицательная поддерживающая сила означает, что нужно давить вниз. Движение свободного тела не моделируется.',steps:['Поставь плотность тела 800, жидкости 1000 кг/м³. Найди долю погружения, при которой поддержка не нужна.','Увеличь объём вдвое: сравни обе силы.','Поставь ρт = 1500 кг/м³ и объясни, почему тело тонет.'],question:'Вычисли силу Архимеда при полном погружении, Н.',answer:p=>p.rho*g*p.volume/1000,solution:'При полном погружении Vпогр = V. Переведи литры в м³ (раздели на 1000) и вычисли ρжgV.',presets:[['Плавающее тело',{body:800,rho:1000,part:80}],['Тяжёлое тело',{body:1800,part:100}]]},
{id:'hydrostatic',title:'Гидростатическое давление',group:'Жидкости',grade:'7–8',symbol:'↓',intro:'Опусти датчик в жидкость: глубина важнее формы сосуда.',params:[p('rho','Плотность жидкости',700,1300,10,1000,'кг/м³'),p('depth','Глубина датчика',0,10,.1,3,'м'),p('area','Площадь мембраны',1,100,1,10,'см²')],sweep:'depth',calc(p){const gauge=p.rho*g*p.depth;return{gauge:gauge/1000,absolute:(101325+gauge)/1000,force:gauge*p.area/10000}},metrics:[m('gauge','Избыточное давление','кПа'),m('absolute','Абсолютное давление','кПа'),m('force','Сила от перепада','Н')],graph:{key:'gauge',label:'Избыточное давление',unit:'кПа'},formula:'pизб = ρgh; pабс = pатм + ρgh; F = pизбS',explain:'Каждый нижний слой удерживает столб жидкости над собой. Давление зависит от глубины и плотности, но не от площади датчика. Площадь определяет силу при данном перепаде давлений.',limits:'Покоящаяся несжимаемая жидкость, pатм = 101325 Па. На обратной стороне мембраны — атмосферное давление. g = 9,81 м/с².',steps:['Запиши давление на глубинах 2, 4 и 6 м.','Увеличь площадь датчика: что изменится в показаниях?','По наклону графика p(h) восстанови плотность жидкости.'],question:'Вычисли избыточное давление на выбранной глубине, кПа.',answer:(p,r)=>r.gauge,solution:'p = ρgh. Результат в паскалях раздели на 1000, чтобы получить кПа.',presets:[['Вода',{rho:1000}],['Масло',{rho:900}]]},
{id:'gas',title:'Газ под поршнем',group:'Тепло',grade:'10',symbol:'pV',intro:'Сожми газ при постоянной температуре и исследуй изотерму.',params:[p('n','Количество вещества',.1,2,.1,1,'моль'),p('T','Температура',200,600,10,300,'К'),p('V','Объём',5,50,.5,20,'л')],sweep:'V',calc(p){return{pressure:p.n*R*p.T/p.V,energy:1.5*p.n*R*p.T,pv:p.n*R*p.T}},metrics:[m('pressure','Давление','кПа'),m('energy','Внутренняя энергия','Дж'),m('pv','Произведение pV','Дж')],graph:{key:'pressure',label:'Давление p',unit:'кПа'},formula:'pV = nRT; U = 3nRT/2',explain:'При постоянных n и T произведение pV неизменно: уменьшение объёма вдвое удваивает давление. Температура задаёт среднюю кинетическую энергию молекул.',limits:'Идеальный одноатомный газ, квазистатическое изменение объёма и теплообмен с термостатом. Частицы на схеме обозначают газ, их количество не равно числу молекул.',steps:['Закрепи изотерму при 300 К, затем построй при 600 К.','При одной температуре сравни pV в трёх точках.','Объясни, куда уходит работа при изотермическом сжатии.'],question:'Рассчитай давление газа, кПа.',answer:(p,r)=>r.pressure,solution:'p = nRT/V. При V в литрах численное значение получается в кПа: 1 кПа·л = 1 Дж. R = 8,314462618 Дж/(моль·К).',presets:[['Холодный газ',{T:200}],['Горячий газ',{T:600}]]},
{id:'heating',title:'Нагрев воды',group:'Тепло',grade:'8–10',symbol:'Q',intro:'Сопоставь мощность нагревателя, время и изменение температуры.',params:[p('mass','Масса воды',.2,3,.1,1,'кг'),p('power','Мощность',100,2000,50,500,'Вт'),p('initial','Начальная температура',10,40,1,20,'°C')],duration:p=>p.mass*4200*(90-p.initial)/p.power,calc(p,t){const Q=p.power*t;return{Q:Q/1000,T:p.initial+Q/(p.mass*4200),rate:p.power/(p.mass*4200),time:p.mass*4200*(90-p.initial)/p.power}},metrics:[m('T','Температура','°C'),m('Q','Полученное тепло','кДж'),m('rate','Скорость нагрева','°C/с'),m('time','Время до 90 °C','с')],graph:{key:'T',label:'Температура',unit:'°C'},formula:'Q = Pt = cm(T − T₀)',explain:'Чем больше масса, тем больше энергии нужно для того же изменения температуры. При постоянной мощности температура растёт линейно, если тепло не уходит наружу.',limits:'cводы = 4200 Дж/(кг·°C), потерь и теплоёмкости сосуда нет. Нагрев только до 90 °C: кипение и испарение в этот опыт не входят.',steps:['Измерь время нагрева до 90 °C.','Удвой массу при той же мощности: сравни наклон графика.','Удвой мощность и сформулируй зависимость времени нагрева.'],question:'Сколько килоджоулей нужно для нагрева выбранной массы на 10 °C?',answer:p=>42*p.mass,solution:'Q = cmΔT = 4200 · m · 10 Дж = 42m кДж.',presets:[['Слабый нагрев',{power:250}],['Мощный нагрев',{power:1500}]]},
{id:'mixing',title:'Тепловой баланс',group:'Тепло',grade:'8–10',symbol:'⇌',intro:'Смешай горячую и холодную воду и найди равновесную температуру.',params:[p('hotMass','Масса горячей воды',.1,3,.1,1,'кг'),p('coldMass','Масса холодной воды',.1,3,.1,1,'кг'),p('hot','Горячая вода',50,95,1,80,'°C'),p('cold','Холодная вода',5,40,1,20,'°C')],sweep:'hotMass',calc(p){const T=(p.hotMass*p.hot+p.coldMass*p.cold)/(p.hotMass+p.coldMass),Q=4200*p.hotMass*(p.hot-T)/1000;return{T,Q,received:4200*p.coldMass*(T-p.cold)/1000}},metrics:[m('T','Равновесная температура','°C'),m('Q','Отданное тепло','кДж'),m('received','Полученное тепло','кДж')],graph:{key:'T',label:'Температура смеси',unit:'°C'},formula:'m₁c(T₁ − T) = m₂c(T − T₂)',explain:'Равновесная температура — среднее, взвешенное по массам. Она всегда между исходными температурами. Тепло, отданное горячей водой, равно полученному холодной.',limits:'Оба вещества — вода с одинаковой постоянной теплоёмкостью. Теплообмен с комнатой и сосудом отсутствует. Показывается итог смешивания, а не его скорость.',steps:['Смешай равные массы и проверь среднее арифметическое температур.','Увеличь горячую массу втрое. К какой температуре приблизился результат?','Сравни отданное и полученное тепло в журнале.'],question:'Найди температуру смеси, °C.',answer:(p,r)=>r.T,solution:'T = (mгорTгор + mхолTхол) / (mгор + mхол). Теплоёмкость сокращается, потому что обе жидкости — вода.',presets:[['Равные массы',{hotMass:1,coldMass:1}],['Больше холодной',{hotMass:.5,coldMass:2}]]},
{id:'ohm',title:'Закон Ома',group:'Электричество',grade:'8–10',symbol:'Ω',intro:'Сними вольт-амперную характеристику резистора.',params:[p('U','Напряжение',0,24,.5,12,'В'),p('resistance','Сопротивление',10,200,5,60,'Ом')],sweep:'U',calc(p){return{I:p.U/p.resistance,P:p.U*p.U/p.resistance,R:p.resistance}},metrics:[m('I','Ток амперметра','А'),m('P','Мощность нагрева','Вт'),m('R','Сопротивление','Ом')],graph:{key:'I',label:'Сила тока I',unit:'А'},formula:'I = U/R; P = UI = U²/R',explain:'Наклон графика I(U) равен проводимости 1/R. Удвоение напряжения удваивает ток, но увеличивает мощность в четыре раза.',limits:'Идеальный источник и измерительные приборы. Сопротивление не меняется с температурой; провода идеальные.',steps:['Запиши ток при 4, 8 и 12 В.','Из отношения ΔU/ΔI восстанови сопротивление.','Увеличь R вдвое и сравни обе характеристики.'],question:'Вычисли мощность резистора, Вт.',answer:(p,r)=>r.P,solution:'P = UI, а I = U/R. Поэтому P = U²/R.',presets:[['Малое сопротивление',{resistance:20}],['Большое сопротивление',{resistance:150}]]},
{id:'circuits',title:'Соединение резисторов',group:'Электричество',grade:'8–10',symbol:'⏛',intro:'Перестрой цепь и сравни распределение токов и напряжений.',params:[p('U','Напряжение источника',1,24,.5,12,'В'),p('r1','Резистор R₁',10,200,5,40,'Ом'),p('r2','Резистор R₂',10,200,5,80,'Ом'),{key:'mode',label:'Соединение',value:1,options:[[1,'Последовательное'],[2,'Параллельное']]}],sweep:'r2',calc(p){const parallel=p.mode===2,R=parallel?p.r1*p.r2/(p.r1+p.r2):p.r1+p.r2,I=p.U/R;return{R,I,I1:parallel?p.U/p.r1:I,I2:parallel?p.U/p.r2:I,U1:parallel?p.U:I*p.r1,U2:parallel?p.U:I*p.r2}},metrics:[m('R','Эквивалентное R','Ом'),m('I','Общий ток','А'),m('I1','Ток в R₁','А'),m('I2','Ток в R₂','А')],graph:{key:'I',label:'Общий ток',unit:'А'},formula:'Rпосл = R₁ + R₂; 1/Rпар = 1/R₁ + 1/R₂',explain:'При последовательном соединении ток общий, а напряжения складываются. При параллельном соединении напряжение общее, а складываются токи ветвей.',limits:'Идеальные резисторы и источник без внутреннего сопротивления. Замыкания и обрывы в этот опыт не включены.',steps:['При последовательном соединении проверь U₁ + U₂ = U.','При параллельном соединении проверь I₁ + I₂ = I.','Увеличь R₂. Объясни, почему ток первой параллельной ветви не изменился.'],question:'Найди эквивалентное сопротивление, Ом.',answer:(p,r)=>r.R,solution:'Последовательно: R = R₁ + R₂. Параллельно: R = R₁R₂ / (R₁ + R₂).',presets:[['Последовательно',{mode:1}],['Параллельно',{mode:2}]]},
{id:'capacitor',title:'Зарядка конденсатора',group:'Электричество',grade:'10–11',symbol:'⊣⊢',intro:'Исследуй переходный процесс: заряд растёт, ток затухает.',params:[p('U','Напряжение',1,24,1,12,'В'),p('resistance','Сопротивление',1,20,.5,5,'кОм'),p('C','Ёмкость',100,2000,50,1000,'мкФ')],duration:p=>5*p.resistance*p.C/1000,calc(p,t){const tau=p.resistance*p.C/1000,k=Math.exp(-t/tau),Uc=p.U*(1-k);return{Uc,I:p.U/p.resistance*k,Q:p.C*Uc/1000,E:.5*p.C/1e6*Uc*Uc,tau}},metrics:[m('Uc','Напряжение на C','В'),m('I','Ток','мА'),m('Q','Заряд','мКл'),m('tau','Постоянная времени','с')],graph:{key:'Uc',label:'Напряжение на C',unit:'В'},formula:'Uс = U(1 − e⁻ᵗ/ᴿᶜ); I = (U/R)e⁻ᵗ/ᴿᶜ; τ = RC',explain:'Вначале незаряженный конденсатор пропускает максимальный ток. Через время τ его напряжение достигает около 63,2% напряжения источника; за 5τ — около 99,3%.',limits:'Изначально конденсатор разряжен; источник идеальный, утечки и сопротивление проводов отсутствуют. Модель зарядки, не переменного тока.',steps:['Поставь время t = τ с помощью шкалы и измерь Uс/U.','Удвой сопротивление: сравни начальный ток и длительность зарядки.','Удвой ёмкость: объясни изменение заряда при том же конечном напряжении.'],question:'Вычисли постоянную времени τ, с.',answer:(p,r)=>r.tau,solution:'τ = RC. При R в кОм и C в мкФ: τ = R · C / 1000 секунд.',presets:[['Быстрая зарядка',{resistance:1,C:500}],['Медленная зарядка',{resistance:10,C:1500}]]},
{id:'induction',title:'Электромагнитная индукция',group:'Электричество',grade:'9–11',symbol:'Φ',intro:'Вращай рамку в магнитном поле и получай переменную ЭДС.',params:[p('B','Магнитная индукция',.1,1,.05,.3,'Тл'),p('area','Площадь рамки',10,100,5,50,'см²'),p('N','Число витков',1,100,1,50),p('f','Частота вращения',.5,5,.1,1,'Гц')],duration:p=>3/p.f,calc(p,t){const w=2*Math.PI*p.f,A=p.area/10000,angle=w*t;return{flux:p.B*A*Math.cos(angle)*1000,emf:p.N*p.B*A*w*Math.sin(angle),max:p.N*p.B*A*w,angle:angle*180/Math.PI}},metrics:[m('flux','Поток через один виток','мВб'),m('emf','ЭДС рамки','В'),m('max','Амплитуда ЭДС','В')],graph:{key:'emf',label:'ЭДС ε',unit:'В'},formula:'Φ = BS cos(ωt); ε = −N dΦ/dt = NBSω sin(ωt)',explain:'ЭДС определяется скоростью изменения потока, а не самим потоком. Когда поток максимален, ЭДС равна нулю. Когда рамка проходит через нулевой поток, модуль ЭДС максимален.',limits:'Однородное постоянное магнитное поле, равномерное вращение рамки. Цепь разомкнута: показана ЭДС, ток и торможение не рассчитываются.',steps:['Сопоставь момент максимального потока с показанием ЭДС.','Удвой число витков, сохрани частоту.','Удвой частоту: объясни одновременно более высокий и более частый сигнал.'],question:'Вычисли амплитуду ЭДС, В.',answer:(p,r)=>r.max,solution:'εₘ = NBS · 2πf. Площадь из см² переведи в м², разделив на 10000.',presets:[['Медленное вращение',{f:.5}],['Быстрое вращение',{f:3}]]},
{id:'wave',title:'Бегущая волна',group:'Волны и оптика',grade:'9–11',symbol:'∿',intro:'Отдели движение волны от колебаний частиц среды.',params:[p('A','Амплитуда',.1,1,.05,.5,'м'),p('f','Частота',.5,3,.1,1,'Гц'),p('speed','Скорость волны',1,6,.5,3,'м/с'),p('probe','Координата датчика',0,10,.1,3,'м')],duration:p=>4/p.f,calc(p,t){return{y:p.A*Math.sin(2*Math.PI*(p.f*t-p.f*p.probe/p.speed)),lambda:p.speed/p.f,T:1/p.f,speed:p.speed}},metrics:[m('y','Смещение датчика','м'),m('lambda','Длина волны','м'),m('T','Период','с'),m('speed','Скорость переноса','м/с')],graph:{key:'y',label:'Смещение датчика',unit:'м'},formula:'y(x,t) = A sin(2πft − 2πx/λ); λ = v/f',explain:'Гребни движутся вправо, но выбранная частица среды колеблется вверх-вниз. Увеличение частоты при той же скорости уменьшает расстояние между гребнями.',limits:'Идеальная одномерная поперечная гармоническая волна без затухания и дисперсии. Амплитуда на рисунке увеличена для наглядности.',steps:['Следи за отмеченной частицей: движется ли она вместе с гребнем?','Удвой частоту при прежней скорости и измерь λ.','Перемести датчик на одну длину волны и сравни фазу.'],question:'Вычисли длину волны, м.',answer:(p,r)=>r.lambda,solution:'За один период гребень проходит λ = vT. Так как T = 1/f, получаем λ = v/f.',presets:[['Длинная волна',{f:.5,speed:3}],['Короткая волна',{f:2,speed:3}]]},
{id:'standing',title:'Стоячая волна на струне',group:'Волны и оптика',grade:'9–11',symbol:'⋈',intro:'Найди узлы, пучности и собственные частоты закреплённой струны.',params:[p('length','Длина струны',.5,3,.1,1,'м'),p('tension','Натяжение',10,100,5,40,'Н'),p('density','Линейная плотность',1,10,.5,4,'г/м'),p('n','Номер гармоники',1,5,1,2)],duration:p=>4/(p.n/(2*p.length)*Math.sqrt(p.tension/(p.density/1000))),calc(p,t){const speed=Math.sqrt(p.tension/(p.density/1000)),f=p.n*speed/(2*p.length);return{speed,f,lambda:2*p.length/p.n,y:Math.cos(2*Math.PI*f*t),nodes:p.n+1}},metrics:[m('f','Собственная частота','Гц'),m('lambda','Длина волны','м'),m('speed','Скорость волны','м/с'),m('nodes','Число узлов','')],graph:{key:'y',label:'Смещение первой пучности / A',unit:''},formula:'fₙ = nv/(2L); v = √(F/μ); y/A = sin(nπx/L) cos(2πfₙt)',explain:'На обоих концах всегда узлы. На длине струны укладывается целое число полуволн. Пучности соседних участков колеблются в противоположных фазах.',limits:'Идеальная однородная струна с неподвижными концами, малые поперечные колебания. Время воспроизведения замедлено; физическое время указано на шкале.',steps:['Переключи гармоники 1–5 и сосчитай узлы.','Увеличь натяжение в четыре раза: как изменилась частота?','Удвой длину и объясни изменение основного тона.'],question:'Вычисли частоту выбранной гармоники, Гц.',answer:(p,r)=>r.f,solution:'fₙ = n/(2L) · √(F/μ). Линейную плотность из г/м переведи в кг/м.',presets:[['Основной тон',{n:1}],['Пятая гармоника',{n:5}]]},
{id:'refraction',title:'Преломление света',group:'Волны и оптика',grade:'8–11',symbol:'↘',intro:'Направь луч на границу сред и найди условие полного внутреннего отражения.',params:[p('n1','Показатель первой среды',1,2,.01,1),p('n2','Показатель второй среды',1,2,.01,1.5),p('angle','Угол падения к нормали',0,85,1,40,'°')],sweep:'angle',calc(p){const s=p.n1*Math.sin(rad(p.angle))/p.n2,tir=s>1+1e-12;return{angle2:tir?null:Math.asin(Math.min(1,s))*180/Math.PI,critical:p.n1>p.n2?Math.asin(p.n2/p.n1)*180/Math.PI:null,tir,speed:299792458/p.n2/1e6}},metrics:[m('angle2','Угол преломления','°'),m('critical','Предельный угол','°'),m('speed','Скорость во второй среде','млн м/с')],graph:{key:'angle2',label:'Угол преломления',unit:'°'},formula:'n₁ sin α = n₂ sin β; sin αкр = n₂/n₁ при n₁ > n₂',explain:'При переходе в оптически более плотную среду луч отклоняется к нормали. При выходе в менее плотную среду выше предельного угла преломлённого луча нет.',limits:'Плоская граница, геометрическая оптика. Яркость лучей условна: коэффициенты Френеля и поляризация не вычисляются. Знак «—» означает отсутствие угла или луча.',steps:['Сравни углы при переходе воздух → стекло и стекло → воздух.','Для n₁ = 1,5, n₂ = 1 найди предельный угол.','Перейди за него и объясни, почему график преломления обрывается.'],question:'Найди скорость света во второй среде в млн м/с.',answer:(p,r)=>r.speed,solution:'v = c/n₂, где c = 299792458 м/с. Для ответа в млн м/с раздели ещё на 1000000.',presets:[['Воздух → стекло',{n1:1,n2:1.5,angle:40}],['Полное отражение',{n1:1.5,n2:1,angle:55}]]},
{id:'lens',title:'Собирающая линза',group:'Волны и оптика',grade:'8–11',symbol:'↕',intro:'Построй изображение двумя лучами и исследуй действительное и мнимое изображения.',params:[p('f','Фокусное расстояние',5,20,1,10,'см'),p('d','Расстояние до предмета',2,60,1,25,'см'),p('height','Высота предмета',1,5,.5,3,'см')],sweep:'d',calc(p){const q=Math.abs(p.d-p.f)<1e-9?null:p.f*p.d/(p.d-p.f);return{q,M:q===null?null:-q/p.d,imageHeight:q===null?null:-q*p.height/p.d,power:100/p.f}},metrics:[m('q','Расстояние до изображения','см'),m('M','Увеличение со знаком',''),m('power','Оптическая сила','дптр')],graph:{key:'q',label:'Расстояние до изображения',unit:'см',breakAt:p=>p.f},formula:'1/F = 1/d + 1/fиз; Γ = −fиз/d; D = 1/F (F в метрах)',explain:'За фокусом получается действительное перевёрнутое изображение. Внутри фокуса — мнимое прямое на стороне предмета. В фокусе выходящие лучи параллельны: конечного изображения нет.',limits:'Тонкая собирающая линза и параксиальные лучи. Положительное расстояние изображения — справа от линзы, отрицательное — слева. Схема автоматически меняет масштаб.',steps:['Поставь предмет в 2F и сравни размеры предмета и изображения.','Приближай предмет к F с двух сторон.','Поставь d < F и объясни, почему продолжения лучей нарисованы пунктиром.'],question:'Вычисли оптическую силу линзы, дптр.',answer:(p,r)=>r.power,solution:'D = 1/F при F в метрах. Если F задано в сантиметрах, D = 100/F.',presets:[['Действительное',{f:10,d:25}],['Мнимое',{f:10,d:6}]]},
{id:'photoelectric',title:'Фотоэффект',group:'Квантовая физика',grade:'11',symbol:'hν',intro:'Проверь пороговую частоту: не каждый фотон способен выбить электрон.',params:[p('frequency','Частота света',300,1500,10,800,'ТГц'),p('work','Работа выхода',1.5,5,.1,2.3,'эВ')],sweep:'frequency',calc(p){const photon=hEv*p.frequency*1e12,emits=photon>p.work,K=Math.max(0,photon-p.work);return{photon,K,threshold:p.work/hEv/1e12,stop:emits?K:null,emits}},metrics:[m('photon','Энергия фотона','эВ'),m('K','Макс. кинетическая энергия','эВ'),m('threshold','Пороговая частота','ТГц'),m('stop','Задерживающее напряжение','В')],graph:{key:'K',label:'Макс. энергия электронов',unit:'эВ'},formula:'hν = Aвых + Kmax; ν₀ = Aвых/h; eUз = Kmax',explain:'Часть энергии фотона расходуется на выход из металла. Только избыток становится кинетической энергией электрона. Ниже порога электронов нет: ноль на графике не означает испускание медленных электронов.',limits:'Однофотонный фотоэффект, идеальная поверхность, h = 4,135667696·10⁻¹⁵ эВ·с. Интенсивность и фототок не моделируются; рисунок показывает энергетическое условие.',steps:['Найди частоту начала фотоэмиссии для A = 2,3 эВ.','Увеличь работу выхода и сравни порог.','Выше порога проверь линейность Kmax(ν) и найди наклон.'],question:'Вычисли пороговую частоту, ТГц.',answer:(p,r)=>r.threshold,solution:'ν₀ = Aвых/h. Используй h в эВ·с, затем раздели частоту на 10¹² для перевода в ТГц.',presets:[['Ниже порога',{frequency:400,work:2.3}],['Выше порога',{frequency:1000,work:2.3}]]},
{id:'decay',title:'Радиоактивный распад',group:'Квантовая физика',grade:'9–11',symbol:'½',intro:'Исследуй период полураспада и отличай долю распавшихся ядер от активности.',params:[p('N','Исходное число ядер',1000,100000,1000,10000),p('half','Период полураспада',1,30,1,5,'сут')],duration:p=>5*p.half,timeUnit:'сут',calc(p,t){const N=p.N*Math.pow(2,-t/p.half);return{N,remaining:N/p.N*100,activity:Math.LN2/(p.half*86400)*N,decayed:p.N-N}},metrics:[m('N','Ожидаемое число ядер',''),m('remaining','Оставшаяся доля','%'),m('activity','Активность','Бк'),m('decayed','Ожидаемо распалось','')],graph:{key:'N',label:'Ожидаемое число ядер',unit:''},formula:'N = N₀ · 2⁻ᵗ/ᵀ; A = (ln 2 / T)N',explain:'За каждый период распадается половина оставшихся ядер, а не половина исходных. Активность измеряется в распадах в секунду, поэтому период в формуле A переводится в секунды.',limits:'Статистическое среднее для большого ансамбля. Реальные распады случайны; дробное ожидаемое число ядер допустимо. Вторичные распады дочерних ядер не учитываются.',steps:['Запиши N через один, два и три периода.','Удвой N₀: как изменятся доля и активность?','При том же N сравни активности веществ с разными T.'],question:'Сколько ядер в среднем останется через три периода полураспада?',answer:p=>p.N/8,solution:'После трёх периодов остаётся N₀ · (1/2)³ = N₀/8.',presets:[['Быстрый распад',{half:2}],['Медленный распад',{half:20}]]}
];
function defaults(e){return Object.fromEntries(e.params.map(p=>[p.key,p.value]))}
function normalize(e,raw={}){if(!raw||typeof raw!=='object')raw={};const values=defaults(e);for(const p of e.params){const n=Number(raw[p.key]);if(raw[p.key]===undefined||!Number.isFinite(n))continue;values[p.key]=p.options?(p.options.some(o=>o[0]===n)?n:p.value):Math.max(p.min,Math.min(p.max,n))}return values}
function domain(e,p){if(e.sweep){const q=e.params.find(q=>q.key===e.sweep);return{min:q.min,max:q.max,label:q.label,unit:q.unit}}return{min:0,max:e.duration(p),label:'Время t',unit:e.timeUnit||'с'}}
function sample(e,p,x){return e.sweep?e.calc({...p,[e.sweep]:x},0):e.calc(p,x)}
const api={labs,defaults,normalize,domain,sample,constants:{g,R,hEv}};
if(typeof module!=='undefined'&&module.exports)module.exports=api;else root.matclubLabModels=api;
})(typeof window!=='undefined'?window:globalThis);
